Команды: APP_ENV=testing DB_DATABASE=commerz_test scripts/php84 vendor/bin/phpunit --configuration phpunit.xml <temporary test file>. Первый запуск P7AuditProbeTest включал три сценария, A5 добавлен и запущен отдельно с --filter testRepeatedObservationStillLearnsProviderPaymentId. Классы сохранены здесь полностью для воспроизводимости, product tests не менялись. Сохраните во временные *Test.php и запускайте последовательно вне других DB tests. Assertions задают корректное поведение; на кандидате намеренно RED.

```php
<?php
declare(strict_types=1);

require_once '/home/vostrikov/projects/packages/commerz/packages/sales/tests/Feature/Refunds/Helpers.php';

use Commerz\Money\Money;
use Commerz\Sales\Common\Data\LineQuantity;
use Commerz\Sales\Fulfillments\Data\CreateFulfillment;
use Commerz\Sales\Orders\Data\ExpireOrders;
use Commerz\Sales\Orders\Enums\OrderState;
use Commerz\Sales\Payments\Data\ReconcilePayment;
use Commerz\Sales\Payments\Enums\PaymentStatus;
use Commerz\Sales\Tests\Fixtures\RecordingGateway;
use Commerz\Schema\TableNames;
use Commerz\Testkit\Commerce;
use Illuminate\Support\Facades\DB;

final class P7AuditProbeTest extends Commerz\Sales\Tests\TestCase
{
    use SlsEnvironment;

    protected function setUp(): void
    {
        parent::setUp();
        $this->artisan('migrate')->assertSuccessful();
        slsTruncate();
        RecordingGateway::reset();
        $fake = Commerce::fake();
        $fake->sellables->add(slsSnapshot('fake:a', '100.00'));
        slsConfig(['checkout' => ['require_delivery' => false]]);
    }

    protected function tearDown(): void
    {
        slsTruncate();
        RecordingGateway::reset();
        parent::tearDown();
    }

    public function testExpiryMakesProgressPastBlockedOldestOrder(): void
    {
        $web = slsChannel();
        $blocked = slsPlace(slsCartWith($web, ['fake:a' => 1]));
        $eligible = slsPlace(slsCartWith($web, ['fake:a' => 1]));
        slsPay($blocked);
        $table = app(TableNames::class)->table('orders');
        DB::table($table)->where('id', $blocked->id->value)->update(['payment_due_at' => new DateTimeImmutable('-2 hours')]);
        DB::table($table)->where('id', $eligible->id->value)->update(['payment_due_at' => new DateTimeImmutable('-1 hour')]);
        $first = slsOrders()->expireDue(new ExpireOrders(limit: 1));
        $second = slsOrders()->expireDue(new ExpireOrders(limit: 1));
        fwrite(STDOUT, '\nexpiry probe: '.json_encode(['first_expired' => count($first->expired), 'first_skipped' => $first->skipped, 'second_expired' => count($second->expired), 'second_skipped' => $second->skipped, 'eligible_state' => slsOrders()->find($eligible->id)->state->value])."\n");
        $this->assertSame(OrderState::Cancelled, slsOrders()->find($eligible->id)->state);
    }

    public function testPartialPaymentRefundDoesNotCompleteUnpaidBalance(): void
    {
        $order = slsPlace(slsCartWith(slsChannel(), ['fake:a' => 1]));
        rfCaptured($order, '10.00');
        rfIssue($order, '1.00');
        slsFulfillments()->create(new CreateFulfillment($order->id, [new LineQuantity(slsLine($order, 'fake:a'), 1)]));
        $stored = slsOrders()->find($order->id);
        $nextPayment = slsOutcome(fn () => slsPay($order)->status->value);
        fwrite(STDOUT, '\ncompletion probe: '.json_encode(['state' => $stored->state->value, 'due' => $stored->amountDue->toDecimal(), 'captured' => $stored->captured->toDecimal(), 'refunded' => $stored->refunded->toDecimal(), 'next_payment' => $nextPayment])."\n");
        $this->assertSame(OrderState::Placed, $stored->state);
    }

    public function testPendingPaymentCanAcquireRequiredCustomerAction(): void
    {
        $order = slsPlace(slsCartWith(slsChannel(), ['fake:a' => 1]));
        $payment = slsPay($order, 'recording', meta: ['status' => 'pending']);
        RecordingGateway::scenario(['found' => 'requires_action']);
        $observed = slsPayments()->reconcile(new ReconcilePayment($payment->id));
        fwrite(STDOUT, '\naction probe: '.json_encode(['status' => $observed->status->value, 'action_url' => $observed->actionUrl])."\n");
        $this->assertSame(PaymentStatus::RequiresAction, $observed->status);
    }

    public function testRepeatedObservationStillLearnsProviderPaymentId(): void
    {
        $order = slsPlace(slsCartWith(slsChannel(), ['fake:a' => 1]));
        $payment = slsPay($order);
        slsPayments()->recordEvent(new Commerz\Sales\Payments\Data\RecordPaymentEvent(
            'manual', 'auth-1', Commerz\Sales\Payments\Enums\PaymentEventType::Authorized, paymentReference: $payment->reference,
        ));
        slsPayments()->recordEvent(new Commerz\Sales\Payments\Data\RecordPaymentEvent(
            'manual', 'auth-2', Commerz\Sales\Payments\Enums\PaymentEventType::Authorized,
            paymentReference: $payment->reference, externalPaymentId: 'provider-123',
        ));
        $stored = slsPayments()->find($payment->id);
        $outcome = slsOutcome(fn () => slsPayments()->recordEvent(new Commerz\Sales\Payments\Data\RecordPaymentEvent(
            'manual', 'captured-1', Commerz\Sales\Payments\Enums\PaymentEventType::Captured, externalPaymentId: 'provider-123',
        ))->status->value);
        fwrite(STDOUT, '\nprovider id probe: '.json_encode(['external_id' => $stored->externalId, 'capture_outcome' => $outcome])."\n");
        $this->assertSame('captured', $outcome);
    }
}

