<?php
declare(strict_types=1);
require_once '/home/vostrikov/projects/packages/commerz/packages/sales/tests/Feature/Helpers.php';

use Commerz\Measures\LocalizedText;
use Commerz\Money\Currency;
use Commerz\Money\Money;
use Commerz\Ports\Delivery\Contracts\DeliveryOptions;
use Commerz\Ports\Sellables\Enums\SellableKind;
use Commerz\Sales\Carts\Data\SelectDelivery;
use Commerz\Shipping\Methods\Contracts\Methods;
use Commerz\Shipping\Methods\Data\CreateMethod;
use Commerz\Shipping\Methods\Data\ZoneRate;
use Commerz\Shipping\Options\Internal\DatabaseShippingOptions;
use Commerz\Shipping\Rates\Data\RateSpec;
use Commerz\Shipping\Zones\Contracts\Zones;
use Commerz\Shipping\Zones\Data\CreateZone;
use Commerz\Shipping\Zones\Data\ZoneMember;
use Commerz\Testkit\Commerce;
use Illuminate\Support\Facades\DB;

final class P7DeliveryProbeTest extends Commerz\Sales\Tests\TestCase
{
    protected function defineEnvironment($app): void
    {
        parent::defineEnvironment($app);
        $app['config']->set('commerz.plugins', []);
        $app['config']->set('commerz.stock', 'unlimited');
    }

    protected function commerzProviders(): array
    {
        return [Commerz\CommerzServiceProvider::class, Commerz\Sales\SalesServiceProvider::class, Commerz\Shipping\ShippingServiceProvider::class];
    }

    public function testMixedCartUsesSameThresholdForOptionsAndQuote(): void
    {
        $this->artisan('migrate')->assertSuccessful();
        slsTruncate();
        DB::statement('truncate cmz_shipping_methods, cmz_shipping_zones cascade');
        try {
            $fake = Commerce::fake();
            $fake->sellables->add(slsSnapshot('fake:a', '100.00'), slsSnapshot('fake:svc', '300.00', SellableKind::Service));
            app()->forgetInstance(DeliveryOptions::class);
            app()->singleton(DeliveryOptions::class, DatabaseShippingOptions::class);
            $channel = slsChannel();
            $zone = app(Zones::class)->create(new CreateZone('ru', 'Russia', [ZoneMember::country('RU')]));
            app(Methods::class)->create(new CreateMethod('courier', new LocalizedText(['ru' => 'Courier']), 'manual', [$channel], [
                new ZoneRate($zone->id, Currency::of('RUB'), new RateSpec('flat', ['amount' => Money::of('50.00', 'RUB')]), Money::of('250.00', 'RUB')),
            ]));
            $cart = slsCartWith($channel, ['fake:a' => 1, 'fake:svc' => 1]);
            $shown = slsCarts()->deliveryOptions($cart->id)[0]->price->toDecimal();
            slsCarts()->selectDelivery(new SelectDelivery($cart->id, 'courier'));
            $quoted = slsCarts()->quote($cart->id)->delivery->price->toDecimal();
            fwrite(STDOUT, '\nmixed cart probe: '.json_encode(['shown_delivery' => $shown, 'quoted_delivery' => $quoted])."\n");
            $this->assertSame($shown, $quoted);
        } finally {
            DB::statement('truncate cmz_shipping_methods, cmz_shipping_zones cascade');
            slsTruncate();
        }
    }
}

